sys_script_include.script:
var People = Class.create();
People.prototype = {
    initialize: function() {
    },

	getEmail: function (person) {

		try {
			var grPerson = new GlideRecord('x_34484_job_sear_0_people');
			if (grPerson.get(person)) {
				return grPerson.email;
			}
			return; // return nothing if we don't get a match on person in the people table
		}
		catch {
			gs.error('script person.getEmail threw exception ' + ex.message);
			return; // return nothing if we experience an exception, the admin will need to check the log
		}


	},

	updateEmail: function (record) {

		var person = JSON.parse(record);

		try{
			var grPerson = new GlideRecord('x_34484_job_sear_0_people');
			if (grPerson.get(person.sysId)) {
				grPerson.email = person.email;
				grPerson.update();
				return true; // true means the email was updated
			}			
		}
		catch(ex) {
			gs.error('script person.updateEmail threw exception ' + ex.message);
			return false;
		}
		return false; // return false if we don't get a match on person in the people table

	},

    type: 'People'
};
